<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import type { FlujoCajaFiltros,FlujoCatalogo,MovimientoFlujoCaja } from '../interfaces/movimiento-flujo-caja.interface'
import { anularMovimientoFlujoCaja,buscarCuentasFlujoCaja,listarMovimientosFlujoCaja,obtenerMovimientoFlujoCaja } from '../services/movimiento-flujo-caja'
const blank=():FlujoCajaFiltros=>({periodo_financiero_id:'',cuenta_contable_id:'',fecha_desde:'',fecha_hasta:''})
const filters=reactive(blank()),rows=ref<MovimientoFlujoCaja[]>([]),periods=ref<FlujoCatalogo[]>([]),accounts=ref<FlujoCatalogo[]>([]),accountQuery=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),error=ref(''),success=ref(''),detail=ref<MovimientoFlujoCaja|null>(null),showCancel=ref(false),cancelTarget=ref<MovimientoFlujoCaja|null>(null),cancelReason=ref('')
const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.',money=(v:number)=>new Intl.NumberFormat('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v||0)),date=(v?:string)=>v?new Date(`${v.slice(0,10)}T00:00:00`).toLocaleDateString('es-PE'):'-'
async function load(next=1){loading.value=true;error.value='';try{const r=await listarMovimientosFlujoCaja(filters,next);rows.value=r.data;periods.value=r.periodos||periods.value;accounts.value=r.cuentas_seleccionadas||accounts.value;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(e){error.value=message(e)}finally{loading.value=false}}
async function searchAccounts(){if(accountQuery.value.length<4)return;try{accounts.value=await buscarCuentasFlujoCaja(accountQuery.value)}catch(e){error.value=message(e)}}
function selectAccount(x:FlujoCatalogo){filters.cuenta_contable_id=String(x.id);accountQuery.value=`${x.cta_contable||x.codigo} - ${x.descripcion||x.nombre}`;accounts.value=[x]}
async function view(item:MovimientoFlujoCaja){loading.value=true;try{detail.value=await obtenerMovimientoFlujoCaja(item.id)}catch(e){error.value=message(e)}finally{loading.value=false}}
function openCancel(item:MovimientoFlujoCaja){cancelTarget.value=item;cancelReason.value='';showCancel.value=true}
async function cancel(){if(!cancelTarget.value)return;loading.value=true;error.value='';try{await anularMovimientoFlujoCaja(cancelTarget.value.id,cancelReason.value);success.value='Movimiento de flujo de caja anulado correctamente.';showCancel.value=false;await load(page.value)}catch(e){error.value=message(e)}finally{loading.value=false}}
function clear(){Object.assign(filters,blank());accountQuery.value='';accounts.value=[];load(1)}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Finanzas / Movimientos de flujo de caja</nav><header class="hero"><div class="mark">FC</div><div><small>MIA · FINANZAS · FLUJO DE CAJA</small><h1>Movimientos de flujo de caja</h1><p>Ingresos y egresos generados desde los movimientos financieros.</p></div><strong>{{total}} movimientos</strong></header><p v-if="error" class="flash badmsg">{{error}}</p><p v-if="success" class="flash okmsg">{{success}}</p><form class="filters" @submit.prevent="load(1)"><select v-model="filters.periodo_financiero_id"><option value="">Todos los periodos</option><option v-for="x in periods" :key="x.id" :value="x.id">{{x.anio}} · {{x.descripcion}} · {{x.estado_ejercicio}}</option></select><div class="account"><input v-model.trim="accountQuery" placeholder="Buscar cuenta de tesorería" @input="searchAccounts"><ul v-if="accounts.length&&accountQuery"><li v-for="x in accounts" :key="x.id" @click="selectAccount(x)">{{x.cta_contable||x.codigo}} · {{x.descripcion||x.nombre}}</li></ul></div><label>Desde<input v-model="filters.fecha_desde" type="date"></label><label>Hasta<input v-model="filters.fecha_hasta" type="date"></label><button>Filtrar</button><button type="button" class="soft" @click="clear">Limpiar</button></form><section class="card"><div v-if="loading" class="empty">Procesando…</div><div v-else-if="!rows.length" class="empty">No se encontraron movimientos de flujo de caja.</div><div v-else class="scroll"><table><thead><tr><th># Flujo</th><th>Movimiento / comprobante</th><th>Fechas</th><th>Cuenta de tesorería</th><th>Tipo</th><th>Concepto</th><th>Quiebre</th><th>Importe</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td><b>#{{item.id}}</b></td><td><b>#{{item.movimiento_id}} · {{item.movimiento?.numero_comprobante}}</b><small>{{item.movimiento?.tipo_comprobante?.detalle}} · {{item.movimiento?.glosa}}</small></td><td>{{date(item.fecha_movimiento)}}<small>Valor: {{date(item.fecha_valor)}}</small></td><td><b>{{item.cuenta_tesoreria?.cuenta_contable?.cta_contable||item.cuenta_contable?.cta_contable}}</b><small>{{item.cuenta_tesoreria?.cuenta_contable?.descripcion||item.cuenta_contable?.descripcion}}</small></td><td><span :class="item.tipo_movimiento==='INGRESO'?'income':'expense'">{{item.tipo_movimiento}}</span></td><td>{{item.concepto?.nombre||'-'}}</td><td>{{item.quiebre?.codigo}}<small>{{item.quiebre?.nombre}}</small></td><td class="number"><b>{{money(item.importe)}}</b></td><td><span :class="item.activo?'good':'bad'">{{item.activo?'ACTIVO':'ANULADO'}}</span></td><td class="actions"><button @click="view(item)">Ver</button><button v-if="item.activo" class="danger" @click="openCancel(item)">Anular</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="dialog"><header><div><small>FLUJO DE CAJA #{{detail.id}}</small><h2>{{detail.tipo_movimiento}} · {{money(detail.importe)}}</h2></div><span :class="detail.activo?'good':'bad'">{{detail.activo?'ACTIVO':'ANULADO'}}</span><button @click="detail=null">×</button></header><div class="facts"><div><small>COMPROBANTE</small><b>{{detail.movimiento?.numero_comprobante}}</b></div><div><small>FECHA MOVIMIENTO / VALOR</small><b>{{date(detail.fecha_movimiento)}} · {{date(detail.fecha_valor)}}</b></div><div><small>CUENTA CONTABLE</small><b>{{detail.cuenta_contable?.cta_contable}} · {{detail.cuenta_contable?.descripcion}}</b></div><div><small>CUENTA EQUIVALENTE</small><b>{{detail.cuenta_equivalente?.cta_contable}} · {{detail.cuenta_equivalente?.descripcion}}</b></div></div><h3>Clasificación</h3><p>Concepto: <b>{{detail.concepto?.nombre||'-'}}</b> · Quiebre: <b>{{detail.quiebre?.nombre||'-'}}</b> · Inversión: <b>{{detail.inversion?.nombre||'-'}}</b> · Código presupuestal: <b>{{detail.cod_presupuestal||'-'}}</b></p><h3>Observación</h3><p>{{detail.observacion||'Sin observación'}}</p><section v-if="!detail.activo" class="cancelled"><b>Motivo de anulación</b><span>{{detail.motivo_anulacion}}</span><small>{{detail.fecha_anulacion}}</small></section></section></div>
<div v-if="showCancel&&cancelTarget" class="backdrop" @mousedown.self="showCancel=false"><form class="dialog cancel" @submit.prevent="cancel"><header><div><small>ANULAR FLUJO DE CAJA</small><h2>#{{cancelTarget.id}} · {{money(cancelTarget.importe)}}</h2></div><button type="button" @click="showCancel=false">×</button></header><p>La anulación afecta únicamente esta participación del movimiento financiero en el flujo de caja.</p><label>Motivo de anulación<textarea v-model.trim="cancelReason" required maxlength="500" rows="5"></textarea></label><footer><button type="button" class="soft" @click="showCancel=false">Cancelar</button><button class="danger" :disabled="loading">Confirmar anulación</button></footer></form></div></div></template>
<style scoped>
.page{--a:#176d78;color:#344750}nav{margin-bottom:15px;color:#91a0a5;font-size:.68rem}nav a{color:var(--a)}.hero{display:flex;align-items:center;gap:14px;padding:20px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:50px;height:50px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero>div:nth-child(2){flex:1}.hero small,.dialog small,.facts small{color:var(--a);font-size:.49rem;font-weight:800}.hero h1{margin:3px 0;font-size:1.3rem}.hero p{margin:0;color:#7c8b91;font-size:.65rem}.hero strong{font-size:.55rem}button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.5rem;cursor:pointer}.soft{color:#607078;background:#edf2f3}.flash{padding:10px;border-radius:6px;font-size:.55rem}.badmsg{color:#9b3d48;background:#fdebee}.okmsg{color:#236c50;background:#e8f7ee}.filters{margin-top:11px;padding:13px;display:grid;grid-template-columns:1.5fr 2fr 1fr 1fr auto auto;gap:7px;background:#fff}.filters label{display:flex;align-items:center;gap:5px;font-size:.5rem}.filters input,.filters select,.dialog textarea{box-sizing:border-box;width:100%;padding:8px;border:1px solid #d5dfe2;border-radius:6px;background:#fff;font-size:.5rem}.account{position:relative}.account ul{position:absolute;z-index:4;width:100%;margin:2px 0;padding:0;border:1px solid #ddd;background:#fff;list-style:none}.account li{padding:8px;font-size:.48rem;cursor:pointer}.card{margin-top:11px;background:#fff}.scroll{overflow:auto}table{width:100%;min-width:1300px;border-collapse:collapse;font-size:.48rem}th,td{padding:9px;border-bottom:1px solid #e3e9eb;text-align:left;vertical-align:top}th{color:#fff;background:#435d6c}td small{display:block;margin-top:3px;color:#829096}.number{text-align:right}.good,.bad,.income,.expense{display:inline-block;padding:4px 7px;border-radius:10px;font-size:.44rem;font-weight:800}.good,.income{color:#267153;background:#e5f7ec}.bad{color:#9d414a;background:#fdebed}.expense{color:#9a4b42;background:#fcede9}.actions{display:flex;gap:4px}.danger{background:#b74b54}.empty{padding:55px;text-align:center}.card>footer,.dialog>footer{padding:12px;display:flex;justify-content:center;gap:8px}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(900px,100%);max-height:92vh;padding:20px;box-sizing:border-box;border-radius:12px;background:#fff;overflow:auto}.dialog>header{display:flex;gap:10px}.dialog>header div{flex:1}.dialog h2{margin:3px 0 15px}.dialog>header button{color:#66757b;background:none;font-size:1.2rem}.facts{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.facts div{display:grid;gap:4px;padding:10px;background:#f1f6f7}.dialog h3{font-size:.65rem}.dialog p,.cancelled{font-size:.53rem}.cancelled{display:grid;gap:5px;padding:12px;color:#923e46;background:#fdebed}.cancel{width:min(560px,100%)}.cancel label{display:grid;gap:5px;font-size:.52rem;font-weight:700}@media(max-width:850px){.filters{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.filters,.facts{grid-template-columns:1fr}.hero{flex-wrap:wrap}.hero .mark{display:none}}
</style>
